-- This script removes all mock demo data (Posts, Alerts, Businesses, Marketplace, Groups, and Profiles)
-- created by the initial seed script, without deleting the Neighborhood boundaries or ANY data that you 
-- personally created as a real user.

DELETE FROM public.group_members WHERE user_id IN ('22222222-2222-2222-2222-222222222221', '22222222-2222-2222-2222-222222222222', '22222222-2222-2222-2222-222222222223');
DELETE FROM public.posts WHERE author_id IN ('22222222-2222-2222-2222-222222222221', '22222222-2222-2222-2222-222222222222', '22222222-2222-2222-2222-222222222223');
DELETE FROM public.alerts WHERE author_id IN ('22222222-2222-2222-2222-222222222221', '22222222-2222-2222-2222-222222222222', '22222222-2222-2222-2222-222222222223');
DELETE FROM public.marketplace_items WHERE seller_id IN ('22222222-2222-2222-2222-222222222221', '22222222-2222-2222-2222-222222222222', '22222222-2222-2222-2222-222222222223');
DELETE FROM public.businesses WHERE owner_id IN ('22222222-2222-2222-2222-222222222221', '22222222-2222-2222-2222-222222222222', '22222222-2222-2222-2222-222222222223') OR owner_id IS NULL;
DELETE FROM public.groups WHERE created_by IN ('22222222-2222-2222-2222-222222222221', '22222222-2222-2222-2222-222222222222', '22222222-2222-2222-2222-222222222223');
DELETE FROM public.profiles WHERE id IN ('22222222-2222-2222-2222-222222222221', '22222222-2222-2222-2222-222222222222', '22222222-2222-2222-2222-222222222223');
DELETE FROM auth.users WHERE id IN ('22222222-2222-2222-2222-222222222221', '22222222-2222-2222-2222-222222222222', '22222222-2222-2222-2222-222222222223');
